package io.github.jdseo921.bootinspection.inspection;

import io.github.jdseo921.bootinspection.common.Verdict;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

/**
 * One board pass as an AOI station reports it.
 *
 * @param externalId generated by the station; sending the same id again is a
 *     no-op, so stations can retry safely
 * @param defects flagged regions; empty for {@code OK}, at least one otherwise
 */
public record InspectionIn(
        @NotNull UUID externalId,
        @NotBlank @Size(max = 64) String serialNumber,
        @NotBlank @Size(max = 32) String lineCode,
        @NotBlank @Size(max = 32) String partNumber,
        @NotNull @Positive Integer profileVersion,
        @NotNull Instant inspectedAt,
        @NotNull Verdict verdict,
        @NotNull @PositiveOrZero @DecimalMax("1.0") Double anomalyScore,
        @NotNull @Positive Integer cycleMs,
        @Size(max = 50) List<@Valid @NotNull DefectIn> defects) {

    public InspectionIn {
        defects = defects == null ? List.of() : List.copyOf(defects);
    }
}
